inline odSensorContributionT *odSensorContribution::UnPack(const ::flatbuffers::resolver_function_t *_resolver) const {
  auto _o = std::make_unique<odSensorContributionT>();
  UnPackTo(_o.get(), _resolver);
  return _o.release();
}

inline void odSensorContribution::UnPackTo(odSensorContributionT *_o, const ::flatbuffers::resolver_function_t *_resolver) const {
  (void)_o;
  (void)_resolver;
  { auto _e = SENSOR_ID(); if (_e) _o->SENSOR_ID = _e->str(); }
  { auto _e = ORIG_SENSOR_ID(); if (_e) _o->ORIG_SENSOR_ID = _e->str(); }
  { auto _e = NUM_ACCEPTED(); _o->NUM_ACCEPTED = _e; }
  { auto _e = NUM_REJECTED(); _o->NUM_REJECTED = _e; }
  { auto _e = WRMS(); _o->WRMS = _e; }
  { auto _e = OB_TYPES(); if (_e) { _o->OB_TYPES.resize(_e->size()); for (::flatbuffers::uoffset_t _i = 0; _i < _e->size(); _i++) { _o->OB_TYPES[_i] = _e->Get(_i)->str(); } } else { _o->OB_TYPES.resize(0); } }
}

inline ::flatbuffers::Offset<odSensorContribution> CreateodSensorContribution(::flatbuffers::FlatBufferBuilder &_fbb, const odSensorContributionT *_o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  return odSensorContribution::Pack(_fbb, _o, _rehasher);
}

inline ::flatbuffers::Offset<odSensorContribution> odSensorContribution::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const odSensorContributionT* _o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  (void)_rehasher;
  (void)_o;
  struct _VectorArgs { ::flatbuffers::FlatBufferBuilder *__fbb; const odSensorContributionT* __o; const ::flatbuffers::rehasher_function_t *__rehasher; } _va = { &_fbb, _o, _rehasher}; (void)_va;
  auto _SENSOR_ID = _o->SENSOR_ID.empty() ? 0 : _fbb.CreateString(_o->SENSOR_ID);
  auto _ORIG_SENSOR_ID = _o->ORIG_SENSOR_ID.empty() ? 0 : _fbb.CreateString(_o->ORIG_SENSOR_ID);
  auto _NUM_ACCEPTED = _o->NUM_ACCEPTED;
  auto _NUM_REJECTED = _o->NUM_REJECTED;
  auto _WRMS = _o->WRMS;
  auto _OB_TYPES = _o->OB_TYPES.size() ? _fbb.CreateVectorOfStrings(_o->OB_TYPES) : 0;
  return CreateodSensorContribution(
      _fbb,
      _SENSOR_ID,
      _ORIG_SENSOR_ID,
      _NUM_ACCEPTED,
      _NUM_REJECTED,
      _WRMS,
      _OB_TYPES);
}

inline OBDT::OBDT(const OBDT &o)
      : ID(o.ID),
        SAT_NO(o.SAT_NO),
        ORIG_OBJECT_ID(o.ORIG_OBJECT_ID),
        ON_ORBIT(o.ON_ORBIT),
        START_TIME(o.START_TIME),
        END_TIME(o.END_TIME),
        METHOD(o.METHOD),
        METHOD_SOURCE(o.METHOD_SOURCE),
        INITIAL_OD(o.INITIAL_OD),
        APRIORI_ID_ELSET(o.APRIORI_ID_ELSET),
        APRIORI_ELSET(o.APRIORI_ELSET),
        APRIORI_ID_STATE_VECTOR(o.APRIORI_ID_STATE_VECTOR),
        APRIORI_STATE_VECTOR(o.APRIORI_STATE_VECTOR),
        LAST_OB_START(o.LAST_OB_START),
        LAST_OB_END(o.LAST_OB_END),
        TIME_SPAN(o.TIME_SPAN),
        FIT_SPAN(o.FIT_SPAN),
        EFFECTIVE_FROM(o.EFFECTIVE_FROM),
        EFFECTIVE_UNTIL(o.EFFECTIVE_UNTIL),
        WRMS(o.WRMS),
        PREVIOUS_WRMS(o.PREVIOUS_WRMS),
        FIRST_PASS_WRMS(o.FIRST_PASS_WRMS),
        BEST_PASS_WRMS(o.BEST_PASS_WRMS),
        ERROR_GROWTH_RATE(o.ERROR_GROWTH_RATE),
        EDR(o.EDR),
        BALLISTIC_COEFF_EST(o.BALLISTIC_COEFF_EST),
        BALLISTIC_COEFF_MODEL(o.BALLISTIC_COEFF_MODEL),
        AGOM_EST(o.AGOM_EST),
        AGOM_MODEL(o.AGOM_MODEL),
        RMS_CONVERGENCE_CRITERIA(o.RMS_CONVERGENCE_CRITERIA),
        NUM_ITERATIONS(o.NUM_ITERATIONS),
        NUM_ACCEPTED_OBS(o.NUM_ACCEPTED_OBS),
        NUM_REJECTED_OBS(o.NUM_REJECTED_OBS),
        ACCEPTED_OB_TYPS(o.ACCEPTED_OB_TYPS),
        ACCEPTED_OB_IDS(o.ACCEPTED_OB_IDS),
        REJECTED_OB_TYPS(o.REJECTED_OB_TYPS),
        REJECTED_OB_IDS(o.REJECTED_OB_IDS) {
  SENSORS.reserve(o.SENSORS.size());
  for (const auto &SENSORS_ : o.SENSORS) { SENSORS.emplace_back((SENSORS_) ? new odSensorContributionT(*SENSORS_) : nullptr); }
}

